#include "reference_owned_scene.h"
#include "owned_scalar_reference_undo_record.h"
#include <iostream>
int main(){try{static_assert(sizeof(void*)==8,"x64 required");for(unsigned seed=0;seed<256;++seed){RecoveredOwnedSceneCandidate s;auto&o=s.create({seed+1,1,0,0});auto&old=s.create({seed+1,2,0,0});auto&next=s.create({seed+1,3,0,0});auto&extra=s.create({seed+1,4,0,0});auto owner=o.record.handle,oldHandle=old.record.handle,nextHandle=next.record.handle;auto&a=s.attach(o,1,{oldHandle});auto token=a.token;for(auto*e:{&o,&old,&next,&extra})e->record.flags|=1;
 {RecoveredOwnedScalarUndoRecordCandidate record(s.references,owner,7,oldHandle,nextHandle,[](auto&){return true;});auto moved=std::move(record);if(old.record.counts!=0x100000||next.record.counts!=0x100000)throw std::runtime_error("retention counts/move");auto matches=[](uint32_t,uint32_t){return true;};s.setScalarReference(token,nextHandle,0,0xffffffffu,matches);s.cleanup({owner},[](auto&,bool){},[](auto&){});if(s.size()!=3||!s.resolve(oldHandle)||!s.resolve(nextHandle))throw std::runtime_error("history roots");auto find=[&](auto&,uint32_t name){return name==7?token:0xffffffffu;};if(!s.replayScalarReference(moved.payload(),true,find,0,0xffffffffu,matches)||a.references()[0]!=oldHandle)throw std::runtime_error("retained undo");if(!s.replayScalarReference(moved.payload(),false,find,0,0xffffffffu,matches)||a.references()[0]!=nextHandle)throw std::runtime_error("retained redo");}
 if(s.resolve(oldHandle)->record.counts||s.resolve(nextHandle)->record.counts)throw std::runtime_error("record release");s.cleanup({owner},[](auto&,bool){},[](auto&){});if(s.size()!=2||s.resolve(oldHandle)||!s.resolve(nextHandle))throw std::runtime_error("released collection");s.cleanup({},[](auto&,bool){},[](auto&){});if(s.size()||s.attributes.size()||s.references.nodes.allocationCount())throw std::runtime_error("final collection");}
 std::cout<<"owned_retained_undo_scenes=256 history_roots_move_replay_release_collection=passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
